const CATALOG={
 '71.001':{name:'White',hex:'#F1F1EB',range:'Vallejo Model Air'},'71.002':{name:'Medium Yellow',hex:'#F5B817',range:'Vallejo Model Air'},
 '71.003':{name:'Red RLM23',hex:'#C92B31',range:'Vallejo Model Air'},'71.004':{name:'Blue',hex:'#3156A6',range:'Vallejo Model Air'},
 '71.007':{name:'Olive Green',hex:'#5D6235',range:'Vallejo Model Air'},'71.057':{name:'Black',hex:'#1E2022',range:'Vallejo Model Air'},
 '71.063':{name:'Silver RLM01',hex:'#A8ADB0',range:'Vallejo Model Air'},'71.066':{name:'Gold',hex:'#B28B39',range:'Vallejo Model Air'},
 '70.951':{name:'White',hex:'#F2F1E8',range:'Vallejo Model Color'},'70.950':{name:'Black',hex:'#202124',range:'Vallejo Model Color'},
 '70. flat red':{name:'Flat Red',hex:'#B83232',range:'Vallejo Model Color'}
};
const starter=['71.001','71.002','71.003','71.004','71.007','71.057','71.063','71.066'].map(code=>({id:crypto.randomUUID(),code,...CATALOG[code]}));
let paintCatalog=Object.entries(CATALOG).map(([code,p])=>({code,...p,line:p.range.replace('Vallejo ','')})),recognizedPaint=null;
const defaultPalettes=[{name:'Vallejo Model Air',use:'do aerografu'},{name:'Vallejo Model Color',use:'do pędzla'}];
const state={paints:load('mp-paints',starter),recipes:load('mp-recipes',[]).map(r=>({...r,mix:r.mix.map(x=>{const {parts,...rest}=x;return {...rest,drops:x.drops??parts??1}})})),palettes:load('mp-palettes',defaultPalettes),target:'#7456D9',mix:[],lightness:86,palette:load('mp-palette','Vallejo Model Air')};
