const L=(pl,en)=>language==='en'?en:pl;
function load(k,f){try{const v=localStorage.getItem(k);return v===null?f:JSON.parse(v)}catch{return f}}function persist(){localStorage.setItem('mp-paints',JSON.stringify(state.paints));localStorage.setItem('mp-recipes',JSON.stringify(state.recipes));localStorage.setItem('mp-palettes',JSON.stringify(state.palettes));localStorage.setItem('mp-palette',JSON.stringify(state.palette))}
function hexRgb(h){h=h.replace('#','');if(h.length===3)h=[...h].map(x=>x+x).join('');return [0,2,4].map(i=>parseInt(h.slice(i,i+2),16))}function rgbHex(r){return '#'+r.map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('').toUpperCase()}
function hsvRgb(h,s,v){let f=(n,k=(n+h/60)%6)=>v-v*s*Math.max(0,Math.min(k,4-k,1));return [f(5),f(3),f(1)].map(x=>x*255)}
function dist(a,b){return Math.sqrt(a.reduce((n,v,i)=>n+(v-b[i])**2,0))}function mixRgb(colors,weights){return [0,1,2].map(ch=>colors.reduce((n,c,i)=>n+Math.pow(c[ch]/255,1.45)*weights[i],0)**(1/1.45)*255)}
function setAccuracy(score){const badge=$('#accuracy');if(score===null){badge.textContent=L('Brak farb','No paints');badge.removeAttribute('style');return}const hue=Math.round(Math.max(0,Math.min(120,(score-52)/48*120)));badge.textContent=`${score}% ${L('zgodności','match')}`;badge.style.setProperty('--accuracy-color',`hsl(${hue} 72% 34%)`);badge.style.setProperty('--accuracy-border',`hsl(${hue} 55% 73%)`);badge.style.setProperty('--accuracy-bg',`hsl(${hue} 72% 95%)`)}
function scoreFromDistance(d){return Math.max(52,Math.round(100-d/4.3))}
function renderPurchaseAdvice(bestDistance=1e9){const box=$('#purchaseAdvice');if(state.palette==='Wszystkie'){box.innerHTML=`<div class="advice-empty">${L('Wybierz konkretną paletę, aby zobaczyć propozycje zakupów.','Choose a specific palette to see purchase suggestions.')}</div>`;return}const line=state.palette.replace('Vallejo ',''),owned=new Set(state.paints.filter(p=>p.range===state.palette).map(p=>p.code)),target=hexRgb(state.target),ownedColors=state.paints.filter(p=>p.range===state.palette).sort((a,b)=>dist(hexRgb(a.hex),target)-dist(hexRgb(b.hex),target)).slice(0,8),missing=paintCatalog.filter(p=>p.line===line&&!owned.has(p.code)).sort((a,b)=>dist(hexRgb(a.hex),target)-dist(hexRgb(b.hex),target)).slice(0,30);if(!missing.length){box.innerHTML=`<div class="advice-empty">${L('Masz już wszystkie kolory z tej palety.','You already own every color in this palette.')}</div>`;return}const current=bestDistance<1e9?scoreFromDistance(bestDistance):0,recommended=missing.map(p=>{let d=dist(hexRgb(p.hex),target);for(const ownedPaint of ownedColors)for(let step=1;step<20;step++){const weight=step/20,mixed=mixRgb([hexRgb(p.hex),hexRgb(ownedPaint.hex)],[weight,1-weight]);d=Math.min(d,dist(mixed,target))}return {...p,projected:scoreFromDistance(d),gain:Math.max(0,scoreFromDistance(d)-current)}}).sort((a,b)=>b.projected-a.projected||b.gain-a.gain).slice(0,3);box.innerHTML=`<div class="advice-head"><div><p class="eyebrow">${L('CO WARTO DOKUPIĆ','WHAT TO BUY')}</p><h3>${L('Bliżej wybranego koloru','Closer to the selected color')}</h3></div><span>${esc(line)}</span></div><div class="advice-list">${recommended.map(p=>`<div class="advice-row"><span class="advice-swatch" style="background:${p.hex}"></span><div><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${L('prognoza','forecast')} ${p.projected}%</small></div>${p.gain? `<b>+${p.gain}%</b>`:''}</div>`).join('')}</div>`}
function calculateMix(){const paints=state.palette==='Wszystkie'?state.paints:state.paints.filter(p=>p.range===state.palette);if(!paints.length){state.mix=[];setAccuracy(null);renderMix();renderPurchaseAdvice();return}const target=hexRgb(state.target);let best={d:1e9,items:[]};const top=[...paints].sort((a,b)=>dist(hexRgb(a.hex),target)-dist(hexRgb(b.hex),target)).slice(0,10);
  for(const p of top){const d=dist(hexRgb(p.hex),target);if(d<best.d)best={d,items:[{paint:p,w:1}]}}
  for(let i=0;i<top.length;i++)for(let j=i+1;j<top.length;j++)for(let a=1;a<20;a++){const w=a/20,r=mixRgb([hexRgb(top[i].hex),hexRgb(top[j].hex)],[w,1-w]),d=dist(r,target);if(d<best.d)best={d,items:[{paint:top[i],w},{paint:top[j],w:1-w}]}}
  const small=top.slice(0,7);for(let i=0;i<small.length;i++)for(let j=i+1;j<small.length;j++)for(let k=j+1;k<small.length;k++)for(let a=1;a<10;a++)for(let b=1;b<10-a;b++){const ws=[a/10,b/10,1-(a+b)/10],r=mixRgb([hexRgb(small[i].hex),hexRgb(small[j].hex),hexRgb(small[k].hex)],ws),d=dist(r,target)+5;if(d<best.d)best={d,items:[{paint:small[i],w:ws[0]},{paint:small[j],w:ws[1]},{paint:small[k],w:ws[2]}]}}
  state.mix=best.items.map(x=>({...x,drops:Math.max(1,Math.round(x.w*10))}));const gcd=(a,b)=>b?gcd(b,a%b):a;const g=state.mix.reduce((n,x)=>gcd(n,x.drops),state.mix[0]?.drops||1);state.mix.forEach(x=>x.drops/=g);setAccuracy(scoreFromDistance(best.d));renderMix();renderPurchaseAdvice(best.d)}
function dropWord(n){const last=n%10,lastTwo=n%100;return n===1?'kropla':last>=2&&last<=4&&(lastTwo<12||lastTwo>14)?'krople':'kropli'}
function renderMix(){const box=$('#mixResult'),graphic=$('#mixInfographic');if(!state.mix.length){graphic.innerHTML='';box.innerHTML=`<div class="empty-state"><strong>${L('Brak farb w tej palecie','No paints in this palette')}</strong>${L('Dodaj kolory do grupy','Add colors to the group')} „${esc(state.palette)}”, ${L('aby utworzyć mieszankę.','to create a mix.')}</div>`;return}graphic.innerHTML=`<div class="mix-segments">${state.mix.map(({paint,drops})=>`<span class="mix-segment" style="background:${paint.hex};flex:${drops}">${drops}</span>`).join('')}</div><div class="mix-legend">${state.mix.map(({paint,drops})=>`<span class="mix-legend-item"><i class="mix-legend-dot" style="background:${paint.hex}"></i>${esc(paint.name)} · ${drops} ${language==='en'?(drops===1?'drop':'drops'):dropWord(drops)}</span>`).join('')}</div>`;box.innerHTML=state.mix.map(({paint,drops})=>`<div class="mix-row"><span class="color-stripe" style="background:${paint.hex}"></span><span class="paint-dot" style="background:${paint.hex}"></span><div><div class="paint-title">${esc(paint.name)}</div><div class="paint-meta">${esc(paint.range)} · ${esc(paint.code)}</div></div><div class="drops"><strong>${drops}</strong><span>${L('KROPLE','DROPS')}</span></div></div>`).join('')}
const coverageTargets=(()=>{const targets=[];for(let h=0;h<360;h+=30)for(const s of [.45,.8,1])for(const v of [.42,.7,1])targets.push(hsvRgb(h,s,v));for(const v of [.15,.35,.55,.75,.95])targets.push(hsvRgb(0,0,v));return targets})();
function coverageScore(paints){if(!paints.length)return 0;const colors=paints.map(p=>hexRgb(p.hex));return Math.round(coverageTargets.reduce((sum,target)=>sum+Math.max(0,100-Math.min(...colors.map(c=>dist(c,target)))/4.3),0)/coverageTargets.length)}
function groupPurchaseAdvice(group,paints){const line=group.name.replace('Vallejo ',''),catalog=paintCatalog.filter(p=>p.line===line);if(!catalog.length)return'';const owned=new Set(paints.map(p=>p.code)),missing=catalog.filter(p=>!owned.has(p.code));if(!missing.length)return`<div class="group-advice"><strong>${L('Paleta kompletna','Complete palette')}</strong><span>${L('Masz wszystkie kolory z tej grupy.','You own every color in this group.')}</span></div>`;const selected=[],working=[...paints],before=coverageScore(working);for(let pick=0;pick<3&&missing.length;pick++){let best=null,bestScore=-1;for(const candidate of missing){if(selected.some(p=>p.code===candidate.code))continue;const score=coverageScore([...working,candidate]);if(score>bestScore){best=candidate;bestScore=score}}if(!best)break;selected.push({...best,coverage:bestScore});working.push(best)}const after=coverageScore(working);return `<div class="group-advice"><div class="group-advice-head"><div><strong>${L('Najlepsze kolejne zakupy','Best next purchases')}</strong><span>${L('Pokrycie całego koła','Full wheel coverage')}: ${before}% → ${after}%</span></div><b>+${Math.max(0,after-before)}%</b></div><div class="group-advice-list">${selected.map((p,i)=>`<button type="button" data-prefill-code="${esc(p.code)}"><span class="advice-swatch" style="background:${p.hex}"></span><span><strong>${i+1}. ${esc(p.name)}</strong><small>${esc(p.code)} · ${L('po dodaniu około','after adding about')} ${p.coverage}%</small></span></button>`).join('')}</div><p>${L('Trzy farby dobrane tak, aby możliwie mocno rozszerzyć całą paletę.','Three paints selected to expand the whole palette as much as possible.')}</p></div>`}
function renderPaints(){const list=$('#paintList');$('#paintCount').textContent=state.paints.length;list.innerHTML=state.palettes.map(group=>{const paints=state.paints.filter(p=>p.range===group.name);return `<section class="palette-group"><div class="palette-group-head"><div><div class="palette-group-title">${esc(group.name)}</div><div class="palette-group-meta">${esc(group.use||L('własna paleta','custom palette'))} · ${paints.length} ${L('kolorów','colors')}</div></div><button class="add-to-palette" type="button" data-add-for="${esc(group.name)}">＋ ${L('Dodaj kolor','Add color')}</button></div>${paints.length?paints.map(p=>`<div class="paint-card"><span class="color-stripe" style="background:${p.hex}"></span><span class="paint-dot" style="background:${p.hex}"></span><div><div class="paint-title">${esc(p.name)}</div><div class="paint-meta">${esc(p.code)}</div></div><button class="delete-button" data-delete-paint="${p.id}">${L('Usuń','Delete')}</button></div>`).join(''):`<div class="palette-group-empty">${L('Ta grupa nie ma jeszcze kolorów.','This group has no colors yet.')}</div>`}${groupPurchaseAdvice(group,paints)}</section>`}).join('')||`<div class="empty-state"><strong>${L('Brak grup','No groups')}</strong>${L('Najpierw dodaj grupę palety.','Add a palette group first.')}</div>`;calculateMix()}
function renderRecipes(){const list=$('#recipeList');list.innerHTML=state.recipes.length?state.recipes.map(r=>`<div class="recipe-card"><span class="color-stripe" style="background:${r.target}"></span><span class="recipe-swatch" style="background:${r.target}"></span><div><div class="paint-title">${esc(r.name)}</div><div class="recipe-palette">${L('Paleta','Palette')}: ${esc(r.palette||L('nie zapisano','not saved'))}</div><div class="paint-meta">${r.mix.map(x=>`${x.drops} ${language==='en'?(x.drops===1?'drop':'drops'):dropWord(x.drops)} · ${esc(x.paint.name)}`).join(' · ')}</div><div class="recipe-date">${r.date}</div></div><button class="delete-button" data-delete-recipe="${r.id}">${L('Usuń','Delete')}</button></div>`).join(''):`<div class="empty-state"><strong>${L('Jeszcze pusto','Nothing here yet')}</strong>${L('Zapisane mieszanki pojawią się tutaj.','Saved mixes will appear here.')}</div>`}
function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
const canvas=$('#colorWheel'),ctx=canvas.getContext('2d');function drawWheel(){const {width:w,height:h}=canvas,c=w/2,rad=w/2;ctx.clearRect(0,0,w,h);for(let a=0;a<360;a+=.6){ctx.beginPath();ctx.moveTo(c,c);ctx.arc(c,c,rad,(a-1)*Math.PI/180,(a+.8)*Math.PI/180);ctx.closePath();ctx.fillStyle=`hsl(${a} 88% 54%)`;ctx.fill()}const g=ctx.createRadialGradient(c,c,0,c,c,rad);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.08,'rgba(255,255,255,.94)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(c,c,rad,0,Math.PI*2);ctx.fill()}
function chooseAt(ev){ev.preventDefault();const rect=canvas.getBoundingClientRect(),x=(ev.clientX-rect.left)/rect.width*canvas.width,y=(ev.clientY-rect.top)/rect.height*canvas.height,c=canvas.width/2,dx=x-c,dy=y-c,r=Math.min(.97,Math.hypot(dx,dy)/c),h=(Math.atan2(dy,dx)*180/Math.PI+360)%360;state.target=rgbHex(hsvRgb(h,r,state.lightness/100));$('#wheelCursor').style.left=`${50+Math.cos(h*Math.PI/180)*r*50}%`;$('#wheelCursor').style.top=`${50+Math.sin(h*Math.PI/180)*r*50}%`;updateTarget()}
function updateTarget(){state.target=state.target.toUpperCase();$('#targetSwatch').style.background=state.target;$('#targetHex').textContent=state.target;$('#hexInput').value=state.target;calculateMix()}
const wheelSurface=$('.color-wheel-wrap');let wheelDragging=false;wheelSurface.addEventListener('pointerdown',e=>{wheelDragging=true;wheelSurface.setPointerCapture(e.pointerId);chooseAt(e)});wheelSurface.addEventListener('pointermove',e=>{if(wheelDragging)chooseAt(e)});wheelSurface.addEventListener('pointerup',e=>{wheelDragging=false;if(wheelSurface.hasPointerCapture(e.pointerId))wheelSurface.releasePointerCapture(e.pointerId)});wheelSurface.addEventListener('pointercancel',()=>wheelDragging=false);$('#toneRange').addEventListener('input',e=>{state.lightness=+e.target.value;const [r,g,b]=hexRgb(state.target),m=Math.max(r,g,b)||1;state.target=rgbHex([r,g,b].map(v=>v/m*255*state.lightness/100));updateTarget()});
$$('.nav-item').forEach(b=>b.onclick=()=>{$$('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.view').forEach(v=>v.classList.remove('active'));$('#'+b.dataset.view).classList.add('active');if(b.dataset.view==='recipesView')renderRecipes()});
function applyLanguage(next=language){language=next;localStorage.setItem('mp-language',JSON.stringify(language));document.documentElement.lang=language;$$('[data-pl][data-en]').forEach(el=>el.textContent=el.dataset[language]);$$('[data-placeholder-pl][data-placeholder-en]').forEach(el=>el.placeholder=el.dataset['placeholder'+(language==='en'?'En':'Pl')]);$$('[data-language]').forEach(b=>b.classList.toggle('active',b.dataset.language===language));renderPalettes();renderPaints();renderRecipes()}
