function renderPalettes(){const choices=[{name:'Wszystkie',use:'wszystkie posiadane'},...state.palettes];$('#mixerPaletteSelect').innerHTML=choices.map(p=>`<option value="${esc(p.name)}">${p.name==='Wszystkie'?L('Wszystkie','All'):esc(p.name)}</option>`).join('');$('#mixerPaletteSelect').value=state.palette}
