$('#paletteForm').onsubmit=e=>{e.preventDefault();const name=$('#paletteName').value.trim(),use=$('#paletteUse').value.trim();if(!name)return;if(state.palettes.some(p=>p.name.toLowerCase()===name.toLowerCase())){toast(L('Taka paleta już istnieje','This palette already exists'));return}state.palettes.push({name,use:use||L('własna paleta','custom palette')});persist();setPalette(name);$('#paletteDialog').close();toast(L('Paleta dodana','Palette added'))};
document.addEventListener('click',e=>{const button=e.target.closest('.close-button');if(!button)return;e.preventDefault();e.stopPropagation();const dialog=button.closest('dialog');if(dialog?.open)dialog.close()},true);
