function normalizePaintCode(value){const clean=value.trim().replace(',','.').replace(/\s+/g,'');return /^\d{5}$/.test(clean)?clean.slice(0,2)+'.'+clean.slice(2):clean}
function recognizePaint(){const code=normalizePaintCode($('#paintCode').value),found=paintCatalog.find(p=>p.code.toLowerCase()===code.toLowerCase());recognizedPaint=found||null;const box=$('#paintSuggestion');$('#paintSubmit').disabled=!found;if(found){box.innerHTML=`<span class="recognition-swatch" style="background:${found.hex}"></span><span><strong>${esc(found.name)}</strong><small>Vallejo ${esc(found.line)} · ${esc(found.code)}</small></span>`;box.classList.remove('hidden')}else if(code.length>=5){box.innerHTML=`<span><strong>${L('Nie znaleziono tego kodu','Code not found')}</strong><small>${L('Sprawdź kod farby Vallejo, np. 71.004','Check the Vallejo paint code, e.g. 71.004')}</small></span>`;box.classList.remove('hidden')}else box.classList.add('hidden')}
$('#paintCode').addEventListener('input',recognizePaint);
$('#paintForm').onsubmit=e=>{e.preventDefault();if(!recognizedPaint){toast(L('Najpierw wpisz prawidłowy kod Vallejo','Enter a valid Vallejo code first'));return}const range='Vallejo '+recognizedPaint.line;if(!state.palettes.some(p=>p.name===range))state.palettes.push({name:range,use:recognizedPaint.line==='Model Air'?L('do aerografu','airbrush'):L('do pędzla','brush painting')});if(state.paints.some(p=>p.code===recognizedPaint.code&&p.range===range)){toast(L('Masz już tę farbę','You already own this paint'));return}state.paints.push({id:crypto.randomUUID(),range,code:recognizedPaint.code,name:recognizedPaint.name,hex:recognizedPaint.hex.toUpperCase()});persist();renderPalettes();renderPaints();$('#paintDialog').close();toast(L('Farba dodana automatycznie','Paint added automatically'))};
$('#paintList').onclick=e=>{const suggestion=e.target.closest('[data-prefill-code]');if(suggestion){openPaintDialog();$('#paintCode').value=suggestion.dataset.prefillCode;recognizePaint();return}const add=e.target.closest('[data-add-for]');if(add){openPaintDialog(add.dataset.addFor);return}const id=e.target.dataset.deletePaint;if(id){state.paints=state.paints.filter(p=>p.id!==id);persist();renderPaints();toast('Farba usunięta')}};$('#recipeList').onclick=e=>{const id=e.target.dataset.deleteRecipe;if(id){state.recipes=state.recipes.filter(r=>r.id!==id);persist();renderRecipes();toast('Receptura usunięta')}};
$('#saveRecipe').onclick=()=>{if(!state.mix.length){toast('Najpierw dodaj farby');return}$('#recipeName').value='';$('#recipePreview').innerHTML=`<div class="paint-title" style="color:${state.target}">${state.target}</div><div class="recipe-palette">Paleta: ${esc(state.palette)}</div><div class="paint-meta">${state.mix.map(x=>`${x.drops} ${dropWord(x.drops)} · ${esc(x.paint.name)}`).join(' · ')}</div>`;$('#recipeDialog').showModal()};
