$('#adjustForm').onsubmit=e=>{e.preventDefault();$$('[data-adjust]').forEach(i=>state.mix[+i.dataset.adjust].drops=Math.max(1,+i.value||1));renderMix();$('#adjustDialog').close();toast('Liczba kropli poprawiona')};
$('#openHex').onclick=()=>$('#hexDialog').showModal();$('#hexForm').onsubmit=e=>{e.preventDefault();const h=$('#hexInput').value;if(!/^#[0-9a-f]{6}$/i.test(h)){toast('Wpisz pełny kod HEX');return}state.target=h;updateTarget();$('#hexDialog').close()};
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installButton').classList.remove('hidden')});$('#installButton').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installButton').classList.add('hidden')}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>reg.update()));
fetch('./vallejo-colors.json?v=8').then(r=>r.json()).then(data=>{paintCatalog=data.colors.map(p=>({...p,range:'Vallejo '+p.line}));if($('#paintDialog').open)recognizePaint();renderPaints()}).catch(()=>{});
drawWheel();applyLanguage(language);setPalette(state.palette);updateTarget();
